#!/usr/bin/env bash
# Repository checks, run by CI after the Android release build.
# Locally: (cd android && ./gradlew :app:assembleRelease -Punsigned) && bash .github/checks.sh
set -euo pipefail
cd "$(dirname "$0")/.."
fail=0
bad() { echo "FAIL: $*"; fail=1; }

# (a) The merged release manifest asks only for permissions listed in docs/permissions.txt.
manifests=$(find android/app/build/intermediates/merged_manifest/release -name AndroidManifest.xml 2>/dev/null || true)
if [ -z "$manifests" ]; then
  bad "no merged release manifest: run ./gradlew :app:assembleRelease in android/ first"
else
  allowed=$(sed -e '/^#/d' -e '/^[[:space:]]*$/d' docs/permissions.txt | sort -u)
  for m in $manifests; do
    asked=$(grep -oE '<uses-permission[^>]*android:name="[^"]+"' "$m" | sed -E 's/.*android:name="([^"]+)"/\1/' | sort -u || true)
    extra=$(comm -23 <(echo "$asked" | sed '/^$/d') <(echo "$allowed" | sed '/^$/d'))
    if [ -n "$extra" ]; then bad "permission not in docs/permissions.txt ($m):"; echo "$extra"; fi
  done
fi

# (b) Text: no long or short dashes, no mention of a writing assistant, no personal paths or
#     addresses, no overclaiming words. In files, file names and commit messages.
dashes=$(printf '\xe2\x80\x93|\xe2\x80\x94')
if git grep -nIE "$dashes" -- . ; then bad "use commas or periods instead of long dashes"; fi
assistant='cla[u]de|generated by a[i]|co-authored-b[y]|chatgp[t]'
if git grep -nIiE "$assistant" -- . ; then bad "remove these mentions"; fi
if git ls-files | grep -iE '(^|/)(\.cla[u]de|cla[u]de\.md)' ; then bad "remove these files"; fi
if git log --format=%B 2>/dev/null | grep -iE "$assistant" ; then bad "commit messages mention a writing assistant"; fi
if git grep -nIE '/[U]sers/|@gmai[l]\.com' -- . ; then bad "remove personal paths and addresses"; fi
if git grep -nIiE 'military[ -]grad[e]|inviolabl[e]|100 ?% secur[e]|anonymou[s]' -- . ':!LICENSE' ':!relay/LICENSE' ; then bad "remove overclaiming words"; fi

# (c) The latest security review is less than 6 months old.
latest=$(ls docs/security | grep -E '^[0-9]{4}-[0-9]{2}-[0-9]{2}\.md$' | sort | tail -1 | sed 's/\.md$//' || true)
if [ -z "$latest" ]; then bad "no security review in docs/security"
else
  limit=$(date -u -d '6 months ago' +%F 2>/dev/null || date -u -v-6m +%F)
  if [[ "$latest" < "$limit" ]]; then bad "last security review $latest is older than 6 months"; fi
fi

# (d) CHANGELOG.md has an entry for each version: Android versionName, Mac MARKETING_VERSION, relay.
android=$(sed -nE 's/^[[:space:]]*versionName = "([^"]+)".*/\1/p' android/app/build.gradle.kts)
mac=$(sed -nE 's/^[[:space:]]*MARKETING_VERSION: "([^"]+)".*/\1/p' mac/project.yml | head -1)
relay=$(sed -nE 's/^[[:space:]]*"version": "([^"]+)".*/\1/p' relay/package.json | head -1)
for v in "$android" "$mac" "$relay"; do
  if [ -z "$v" ]; then bad "a version could not be read"; continue; fi
  if ! grep -qE "^## ${v//./\\.}([[:space:]]|$)" CHANGELOG.md; then bad "CHANGELOG.md has no entry for $v"; fi
done

# (e) Sizes and colors come from the token files only.
if grep -rnE '[0-9]f?\.(dp|sp)\b|Color\(0x' android/app/src/main/java --include='*.kt' | grep -v '/Tokens\.kt:' ; then
  bad "Android: use Tokens for sizes and colors"
fi
if grep -rnE 'Color\((red|\.sRGB|hue|white):|NSColor\((red|srgbRed|calibratedRed)|#colorLiteral' mac/Clipway --include='*.swift' | grep -v '/Tokens\.swift:' ; then
  bad "Mac: use Tokens for colors"
fi

# (f) docs/VECTORS.json matches tools/gen-vectors.mjs.
if command -v node >/dev/null; then
  before=$(git hash-object docs/VECTORS.json)
  node tools/gen-vectors.mjs >/dev/null
  if [ "$before" != "$(git hash-object docs/VECTORS.json)" ]; then bad "docs/VECTORS.json is out of date: commit the regenerated file"; fi
fi

# (g) The Mac app has exactly the sandbox entitlements listed in docs/entitlements-mac.txt.
want=$(sed -e '/^#/d' -e '/^[[:space:]]*$/d' docs/entitlements-mac.txt | sort -u)
got=$(grep -oE '<key>[^<]+</key>' mac/Clipway/Clipway.entitlements | sed -E 's#</?key>##g' | sort -u)
if [ "$want" != "$got" ]; then bad "Mac entitlements differ from docs/entitlements-mac.txt"; diff <(echo "$want") <(echo "$got") || true; fi

[ "$fail" = 0 ] && echo "Repository checks passed (android $android, mac $mac, relay $relay, last review $latest)"
exit "$fail"
